publicBundle.renderScript:
window.GeneratedLayouts = window.GeneratedLayouts || {};
window.GeneratedLayouts['public_vitrine_9eed8c9105'] = {
  mount(root, ctx) {
    const { collections, helpers, assets } = ctx;
    root.innerHTML = '';
    root.classList.add('public_vitrine_9eed8c9105-root');

    const giltSVG = assets && assets['gilt-corner'] ? assets['gilt-corner'] : '';

    // Index panel
    const indexPanel = document.createElement('div');
    indexPanel.className = 'index-panel';

    const indexTab = document.createElement('div');
    indexTab.className = 'index-tab';
    indexTab.innerHTML = '<span>Index</span>';
    indexTab.setAttribute('aria-label', 'Toggle specimen index');
    indexPanel.appendChild(indexTab);

    const indexHeader = document.createElement('div');
    indexHeader.className = 'index-header';
    indexHeader.innerHTML = 'Cabinet Index<div class="index-subtitle">Classified Specimens</div>';
    indexPanel.appendChild(indexHeader);

    const indexList = document.createElement('div');
    indexList.className = 'index-list';
    indexPanel.appendChild(indexList);

    let indexOpen = false;
    indexTab.addEventListener('click', () => {
      indexOpen = !indexOpen;
      indexPanel.classList.toggle('open', indexOpen);
    });

    root.appendChild(indexPanel);

    // Main area
    const main = document.createElement('div');
    main.className = 'public_vitrine_9eed8c9105-main';

    // Header
    const header = document.createElement('div');
    header.className = 'public_vitrine_9eed8c9105-header';
    header.innerHTML = '<div class="public_vitrine_9eed8c9105-title">Cabinet of Curiosities</div><div class="public_vitrine_9eed8c9105-subtitle">A Collection of Specimens &amp; Works</div><div class="public_vitrine_9eed8c9105-rule"><div class="public_vitrine_9eed8c9105-rule-line"></div><span style="color:var(--color-accent);font-size:1rem;">&#10022;</span><div class="public_vitrine_9eed8c9105-rule-line"></div></div>';
    main.appendChild(header);

    // Lightbox
    const lightbox = document.createElement('div');
    lightbox.className = 'lightbox-overlay';
    lightbox.innerHTML = '<div class="lightbox-inner"><button class="lightbox-close">&#10005;</button><img src="" alt=""><div class="lightbox-caption"></div></div>';
    root.appendChild(lightbox);
    const lbImg = lightbox.querySelector('img');
    const lbCaption = lightbox.querySelector('.lightbox-caption');
    lightbox.querySelector('.lightbox-close').addEventListener('click', () => {
      lightbox.classList.remove('active');
    });
    lightbox.addEventListener('click', (e) => {
      if (e.target === lightbox) lightbox.classList.remove('active');
    });

    let specimenCount = 0;

    collections.forEach((col, ci) => {
      const colIdx = col.originalIndex !== undefined ? col.originalIndex : ci;

      // Index entry
      const idxCol = document.createElement('div');
      idxCol.className = 'index-collection';
      const idxName = document.createElement('div');
      idxName.className = 'index-collection-name';
      idxName.textContent = col.name || ('Collection ' + (colIdx + 1));
      idxCol.appendChild(idxName);
      const idxSpecList = document.createElement('div');
      idxSpecList.className = 'index-specimen-list';
      idxCol.appendChild(idxSpecList);
      indexList.appendChild(idxCol);

      // Collection frame
      const frame = helpers.collectionFrame(col, colIdx, { className: 'collection-section' });
      frame.id = 'collection-' + colIdx;

      const colHeader = document.createElement('div');
      colHeader.className = 'collection-header';
      colHeader.innerHTML = '<span class="collection-header-ornament">&#9670;</span><span class="collection-title">' + (col.name || 'Collection') + '</span><span class="collection-count">' + (col.images ? col.images.length : 0) + ' specimens</span>';
      frame.appendChild(colHeader);

      idxCol.addEventListener('click', () => {
        frame.scrollIntoView({ behavior: 'smooth', block: 'start' });
        if (indexOpen) { indexOpen = false; indexPanel.classList.remove('open'); }
      });

      const grid = document.createElement('div');
      grid.className = 'specimen-grid';
      frame.appendChild(grid);

      (col.images || []).forEach((img, wi) => {
        specimenCount++;
        const specNum = String(specimenCount).padStart(3, '0');
        const specLabel = 'Specimen ' + specNum;

        // Index item
        const idxItem = document.createElement('div');
        idxItem.className = 'index-specimen-item';
        idxItem.innerHTML = '<span class="index-specimen-num">' + specNum + '</span><span>' + specLabel + '</span>';
        idxSpecList.appendChild(idxItem);

        // Card wrapper
        const card = document.createElement('div');
        card.className = 'specimen-card';

        // Gilt corners
        ['tl','tr','bl','br'].forEach(pos => {
          const corner = document.createElement('div');
          corner.className = 'gilt-corner ' + pos;
          if (giltSVG) corner.innerHTML = giltSVG;
          card.appendChild(corner);
        });

        // Image wrap
        const imgWrap = document.createElement('div');
        imgWrap.className = 'specimen-image-wrap';
        const tile = helpers.workTile(img, { className: '', collectionIndex: colIdx, workIndex: wi });
        imgWrap.appendChild(tile);
        card.appendChild(imgWrap);

        // Label
        const label = document.createElement('div');
        label.className = 'specimen-label';
        label.innerHTML = '<div class="specimen-num">' + specLabel + '</div><div class="specimen-name">' + (col.name || 'Work') + '</div>';
        card.appendChild(label);

        // Lightbox click
        card.addEventListener('click', () => {
          const tileImg = tile.querySelector('img');
          if (tileImg) {
            lbImg.src = tileImg.src;
            lbImg.alt = tileImg.alt || specLabel;
          }
          lbCaption.textContent = specLabel + ' — ' + (col.name || '');
          lightbox.classList.add('active');
        });

        idxItem.addEventListener('click', () => {
          card.scrollIntoView({ behavior: 'smooth', block: 'center' });
          card.style.outline = '2px solid var(--color-accent)';
          setTimeout(() => { card.style.outline = ''; }, 1200);
          if (indexOpen) { indexOpen = false; indexPanel.classList.remove('open'); }
        });

        grid.appendChild(card);
      });

      main.appendChild(frame);
    });

    root.appendChild(main);
  }
};
